function home(){const s=DATA.stories[0];app.innerHTML=`<div class="landing"><div class="hero-bg" style="background-image:linear-gradient(90deg,rgba(10,32,41,.96) 0%,rgba(10,32,41,.90) 31%,rgba(10,32,41,.36) 70%,rgba(10,32,41,.10) 100%),url('${art(s)}')"></div>${topNav()}<main class="hero-layout"><div class="hero-text"><span class="tiny-caps">✦ NUEVA EDICIÓN · CAMINOS DE FE V24</span><h1>24 RELATOS. <em>PERSONAJES QUE CUENTAN LA HISTORIA.</em></h1><p>Descubre relatos bíblicos caminando por mundos ilustrados. Conoce a protagonistas y secundarios, reúne las seis escenas clave y pon a prueba lo aprendido con desafíos y minijuegos.</p><div class="gender-chooser" aria-label="Elige tu protagonista"><span>ELIGE TU PROTAGONISTA</span><button type="button" data-gender="female" aria-pressed="${state.gender!=='male'}"><img src="${asset('assets/protagonistas-v23/female-0.svg')}" alt=""><b>Exploradora</b><small>♀ Mujer</small></button><button type="button" data-gender="male" aria-pressed="${state.gender==='male'}"><img src="${asset('assets/protagonistas-v23/male-0.svg')}" alt=""><b>Explorador</b><small>♂ Hombre</small></button></div><div class="hero-actions"><button class="btn strong" id="start">${state.current?'▶ Continuar la expedición':'▶ Comenzar a explorar'}</button><button class="btn outline" data-go="select">🗺 Explorar los 24 relatos</button></div><div class="hero-stats"><span><b>24</b> relatos</span><span><b>144</b> preguntas con fuentes verificadas</span><span><b>175</b> personajes únicos</span><span><b>12</b> estudios 2026</span></div><div class="hero-secondary"><button data-go="news">✦ Preguntas de La Atalaya 2026</button><button data-go="rewards">🏅 Mi colección y recompensas</button></div></div><div class="hero-showcase"><div class="halo"></div><img class="hero-char" src="${avatarArt()}" alt="Personaje de exploración original en alta resolución"><div class="showcase-bubble bubble-a"><b>ENCUENTRA EL SENTIDO</b><small>Rompecabezas · pupiletras · decisiones</small></div><div class="showcase-bubble bubble-b"><b>AVANZA Y DESCUBRE</b><small>Pistas ocultas en personajes</small></div></div></main><footer class="home-footer">Juego educativo independiente, no afiliado ni respaldado por JW.org. Fuentes externas enlazadas para consulta; paisajes alternativos originales; ilustraciones JW descargables directamente a tu equipo para uso personal.</footer></div>`;
 $$('[data-gender]').forEach(b=>b.onclick=()=>{state.gender=b.dataset.gender;save();render('home')});$('#start').onclick=()=>{if(!state.current)render('select');else render('game')};bindNav()}
function select(){app.innerHTML=`<div class="page-shell">${topNav()}<div class="page-head"><button class="crumb" data-go="home">← INICIO</button><span class="tiny-caps">UN MUNDO DE HISTORIAS</span><h1>Elige tu próxima <em>aventura.</em></h1><p>Elige dónde comienza tu viaje. Conversa con personajes, encuentra pistas, resuelve enigmas y reconstruye cada relato.</p></div><div class="atlas-grid">${DATA.stories.map((s,i)=>`<button class="atlas-card" data-story="${s.id}"><img loading="lazy" src="${art(s)}" alt="Escenario ilustrado original de ${esc(s.name)}"><span class="atlas-shade"></span><span class="atlas-top">RUTA ${String(i+1).padStart(2,'0')} ${progress(s.id).completed?' · ✓ COMPLETADA':''}</span><span class="atlas-bottom"><small>${esc(s.era)}</small><b>${esc(s.name)}</b><span>${esc(s.value)} · ${esc(s.place)}</span></span></button>`).join('')}</div><div class="page-end"><p class="media-note">Las ilustraciones oficiales pueden descargarse para uso estrictamente personal con el iniciador de la edición local; no se incluyen en este paquete.</p><button class="btn outline" data-go="news">Explorar estudios recientes de 2026 →</button></div></div>`;bindNav();$$('[data-story]').forEach(b=>b.onclick=()=>{state.current=b.dataset.story;save();render('game')})}
function updateHud(){if(!$('#hudXp'))return;$('#hudXp').textContent=state.xp.toLocaleString('es-ES');$('#hudCoins').textContent=state.coins;$('#hudLevel').textContent=lev();$('#hudPearls').textContent=progress().pearls.length+'/3';if($('#miniDot'))$('#miniDot').style.left=Math.max(3,Math.min(97,(progress().x/WORLD_WIDTH*100)))+'%';}
function completion(p){return [learnedCharacters(story(),p)>=getPeople(story().id).length,p.pearls.length>=3,p.puzzle,p.wordFound.length>=5,p.timeline,allQuestions(story()).filter(q=>p.quiz[q.id]?.solved).length>=4,p.decision,!!p.storyAssembled]}
function objective(p){const c=completion(p);return !c[0]?'Conoce a todos los personajes del relato':!c[1]?'Investiga las 3 perlas':!c[2]?'Completa el rompecabezas':!c[3]?'Encuentra las 5 palabras':!c[4]?'Ordena los acontecimientos':!c[5]?'Resuelve 4 preguntas':!c[6]?'Toma una decisión para hoy':p.fragments.length<6?'Descubre los 6 momentos clave':!c[7]?'Une las 6 piezas del relato':'¡Dirígete al arco de la victoria!'}
function game(){const s=story(),p=progress();NODES=buildWorldNodes(s);npcArmed=new Set(getPeople(s.id).filter(e=>!hasMet(e,p)).map(e=>e.index));const q=completion(p);const nodes=NODES.map((n,i)=>{const isNPC=n.type==='npc',role=isNPC?roleInfo[n.index%roleInfo.length]:null;const label=isNPC?(getActor(s,n.index)?.name||role[1]):({memory:'Momento clave '+(n.index+1),pearl:'Investigación bíblica',puzzle:'Puzzle de la escena',words:'Sopa de letras',timeline:'Línea de tiempo',quiz:'Desafío de preguntas',finish:'Arco de la victoria'}[n.type]);const d=isNPC?`<img loading="lazy" src="${person(role[0],s,n.index)}" alt=""><small class="npc-caption">${esc(label)}</small><i class="npc-question">${p.talks.includes(n.index)?'✓':'···'}</i>`:n.type==='memory'?`<span class="memory-chapter-icon">${p.fragments.includes(n.index)?'✓':'📜'}</span><small class="world-label memory-chapter-name">Escena ${n.index+1}</small>`:n.type==='pearl'?`<span class="floating-gem">${p.pearls.includes(n.index)?'✓':'💡'}</span><small class="world-label">Investigar · pregunta ${n.index+1}</small>`:`<span class="world-portal portal-${n.type}">${({puzzle:'🧩',words:'🔠',timeline:'⏳',quiz:'📜',finish:'🏆'})[n.type]}</span><small class="world-label">${esc(label)}</small>`;return `<button class="world-node node-${n.type}" data-node="${i}" style="left:${n.x}px;top:${n.y}px" aria-label="${esc(label)}" title="Acércate y pulsa E, o haz clic">${d}</button>`}).join('');
 app.innerHTML=`<div class="gamepage"><header class="gamebar"><button class="game-back" id="backAtlas">← Atlas</button><div class="game-title"><small>EXPEDICIÓN · RELATO BÍBLICO · ${esc(s.era)}</small><b>${esc(s.name)}</b></div><div class="game-hud"><span>✨ <b id="hudXp">${state.xp}</b> XP</span><span>✺ <b id="hudCoins">${state.coins}</b></span><span>LVL <b id="hudLevel">${lev()}</b></span><span>◆ <b id="hudPearls">${p.pearls.length}/3</b></span></div><button class="scene-upload" id="sceneUpload" title="Elegir imagen guardada para el paisaje">▧ Imagen personal</button><button class="scene-upload" id="changeAvatar" title="Cambiar personaje">♟ Personaje</button><button class="game-menu" id="helpMenu" aria-label="Abrir menú">☰</button></header><main class="game-layout"><section class="viewport" id="viewport" aria-label="Escenario interactivo de exploración"><div class="world ${window.JW_LOCAL_ART?.[s.id]?'jw-art':''}" id="world" style="width:${WORLD_WIDTH}px;background-image:url('${art(s)}')"><div class="world-glow glow-a"></div><div class="world-glow glow-b"></div>${nodes}<div class="avatar" id="avatar" style="left:${p.x}px;top:${p.y}px"><img src="${avatarArt()}" alt="Explorador que puedes mover"></div></div><div class="scene-head"><span class="tag">✦ ${esc(s.place)}</span><span class="tiny-label">AVANZA · ACÉRCATE · ESCUCHA</span></div><div class="location-pill" id="locationPill">El inicio del camino</div><div class="mini-map"><div class="mini-line"><span id="miniDot"></span></div><small>INICIO</small><small>FINAL</small></div><div class="control-pad" aria-label="Controles táctiles"><button data-dir="up" aria-label="Arriba">▲</button><div><button data-dir="left" aria-label="Izquierda">◀</button><button data-dir="down" aria-label="Abajo">▼</button><button data-dir="right" aria-label="Derecha">▶</button></div></div><span class="world-tip">WASD/Flechas: caminar · E: hablar · B: historia · P: personaje · G: guía</span><div class="toast" id="toast" role="status" aria-live="polite"></div></section><aside class="quest-panel"><div class="quest-cover" style="background-image:url('${art(s)}')"><small>CAPÍTULO ACTUAL</small><h2>${esc(s.name)}</h2><span>${esc(s.value)}</span></div><div class="quest-scroll"><div class="quest-subhead"><small>✦ DIARIO DE AVENTURA</small><button class="text-link" id="showSources">Ver fuentes ↗</button></div><div class="chronology-widget"><div class="chronology-heading"><b>SECUENCIA DEL RELATO</b><span>DEL INICIO AL DESENLACE</span></div><div class="chronology-steps" id="chronologySteps">${Array.from({length:6},(_,i)=>`<button class="chrono-dot ${p.fragments.includes(i)?'read':''} ${i===0?'first':''}" data-chrono="${i}" aria-label="Ir al personaje ${i+1}" title="Escena ${i+1}"><b>${i+1}</b></button>`).join('')}</div></div><div class="story-discovery"><span>CUADERNO DE RELATO</span><strong id="storyParts">${p.fragments.length}/6 escenas · ${learnedCharacters(s,p)}/${getPeople(s.id).length} personajes</strong><p>Conoce a los personajes una sola vez y recoge seis momentos cronológicos 📜 para reconstruir el relato.</p><button id="storyBook" class="storybook-button">📖 Abrir mi historia <span>→</span></button></div><button class="cast-open" id="castRoster">👥 Conocer a todo el elenco (${getPeople(s.id).length}) <span>→</span></button><div class="next-goal"><div><small>TU PRÓXIMA META</small><b>${esc(objective(p))}</b></div><button class="btn small amber" id="routeBtn">🧭 Llévame</button></div><div class="quest-meter"><span><b>${q.filter(Boolean).length}/8</b> objetivos cumplidos</span><div><i style="width:${q.filter(Boolean).length/8*100}%"></i></div></div><div class="quest-list">${[['Conocer los '+getPeople(s.id).length+' personajes',q[0],'npc'],['Descubrir las 3 perlas',q[1],'pearl'],['Completar el rompecabezas',q[2],'puzzle'],['Resolver la pupiletras',q[3],'words'],['Ordenar el relato',q[4],'timeline'],['Dominar preguntas difíciles',q[5],'quiz'],['Aplicarlo a la vida',q[6],'decision'],['Unir el relato completo',q[7],'story']].map(([a,done,type])=>`<button class="quest-task ${done?'achieved':''}" data-task="${type}"><span class="task-icon">${done?'✓':'○'}</span><span>${esc(a)}</span><span>›</span></button>`).join('')}</div><div class="quest-tools"><button id="quickQuestions" class="btn strong">✦ Desafíos de conocimiento</button><button class="btn outline" id="quickStory">📖 Reconstruir la historia</button><button class="btn outline" id="quickDecision">💬 ¿Qué harías hoy?</button><button class="btn outline" id="quickFinish">🏆 Completar expedición</button></div><p class="tiny-disclaimer">Paráfrasis didácticas, no citas literales. Los personajes anónimos conservan sus nombres de rol; consulta los textos bíblicos.</p></div></aside></main><div class="game-bottom"><span>✦ ${esc(objective(p))}</span><button id="mobileJournal">📜 Desafíos</button><button id="mobileRoute">🧭 Orientación</button></div></div>`;
 $('#castRoster').onclick=showCast;$('#sceneUpload').onclick=()=>chooseArt(story().id);$('#changeAvatar').onclick=pickCharacter;$('#backAtlas').onclick=()=>render('select');$('#helpMenu').onclick=menu;$('#showSources').onclick=sources;$('#quickQuestions').onclick=()=>openQuiz(0);$('#quickStory').onclick=storyBook;$('#storyBook').onclick=storyBook;$('#mobileJournal').onclick=storyBook;$('#quickDecision').onclick=decision;$('#quickFinish').onclick=finish;$('#routeBtn').onclick=routeToNext;$('#mobileRoute').onclick=routeToNext; $$('.quest-task').forEach(b=>b.onclick=()=>routeTask(b.dataset.task));$$('[data-node]').forEach(b=>b.onclick=()=>{const n=NODES[+b.dataset.node];navigate(n)});$$('[data-chrono]').forEach(b=>b.onclick=()=>routeTaskToMemory(+b.dataset.chrono));
 $('#viewport').addEventListener('click',e=>{if(e.target.closest('button')||modalOpen)return;const r=$('#viewport').getBoundingClientRect();const x=e.clientX-r.left+camX,y=e.clientY-r.top+camY;autowalk={x:Math.max(90,Math.min(WORLD_WIDTH-50,x)),y:Math.max(560,Math.min(720,y)),node:null}});
 $$('.control-pad [data-dir]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();held.add(b.dataset.dir);autowalk=null;b.setPointerCapture(e.pointerId)});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>held.delete(b.dataset.dir));b.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();held.add(b.dataset.dir);autowalk=null}});b.addEventListener('keyup',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();held.delete(b.dataset.dir)}})});
 adjustCamera(true);raf=requestAnimationFrame(loop);updateHud()}
function loop(t){if(state.screen!=='game')return;const dt=Math.min(.04,last?(t-last)/1000:.016);last=t;if(!modalOpen){const p=progress();if(bubbleIndex!==null){const bn=NODES.find(n=>n.type==='npc'&&n.index===bubbleIndex);if(bn&&Math.hypot(p.x-bn.x,p.y-bn.y)>180)closeBubble()}let dx=(held.has('right')?1:0)-(held.has('left')?1:0),dy=(held.has('down')?1:0)-(held.has('up')?1:0);if(autowalk&&dx===0&&dy===0){const d=Math.hypot(autowalk.x-p.x,autowalk.y-p.y);if(d<30){const n=autowalk.node;autowalk=null;if(n){interact(n);}}else{dx=(autowalk.x-p.x)/d;dy=(autowalk.y-p.y)/d}}
 const d=Math.hypot(dx,dy);if(d){moving=true;p.x=Math.max(105,Math.min(WORLD_WIDTH-45,p.x+dx/d*345*dt));p.y=Math.max(556,Math.min(712,p.y+dy/d*200*dt));const avatar=$('#avatar');if(avatar){avatar.style.left=p.x+'px';avatar.style.top=p.y+'px';avatar.classList.add('walking');avatar.classList.toggle('reversed',dx<0)}}else if(moving){moving=false;$('#avatar')?.classList.remove('walking');save()};adjustCamera(false);setStageLabel(p.x);placeBubble();checkNpcProximity(p)}raf=requestAnimationFrame(loop)}
function nearestNode(radius=164){const p=progress();return NODES.filter(n=>n.type!=='finish').map(n=>({n,d:Math.hypot(p.x-n.x,p.y-n.y)})).filter(e=>e.d<=radius).sort((a,b)=>a.d-b.d)[0]?.n||null}
function checkNpcProximity(p){if(modalOpen||autowalk?.node&&autowalk.node.type!=='npc')return;for(const n of NODES.filter(n=>n.type==='npc')){const d=Math.hypot(p.x-n.x,p.y-n.y);if(d>225)npcArmed.add(n.index);if(d<155&&npcArmed.has(n.index)&&!p.talks.includes(n.index)){npcArmed.delete(n.index);autowalk=null;held.clear();moving=false;dialogue(n.index,true);break}}}
function adjustCamera(immediate){const v=$('#viewport'),w=$('#world');if(!v||!w)return;const p=progress(),VW=v.clientWidth,VH=v.clientHeight;let x=Math.max(0,Math.min(WORLD_WIDTH-VW,p.x-VW*.43)),y=Math.max(0,Math.min(820-VH,p.y-VH*.63));camX=immediate?x:camX+(x-camX)*.13;camY=immediate?y:camY+(y-camY)*.13;w.style.transform=`translate3d(${-camX}px,${-camY}px,0)`;if($('#miniDot'))$('#miniDot').style.left=(p.x/WORLD_WIDTH*100)+'%'}
function setStageLabel(x){const marks=NODES.filter(n=>n.type==='memory');const phase=Math.max(1,Math.min(6,marks.filter(n=>n.x<=x+110).length));const titles=['EL CONTEXTO','EL CAMBIO','LA PRUEBA','LA DECISIÓN','EL DESENLACE','LAS CONSECUENCIAS'];const label=`ETAPA ${phase}/6 · ${titles[phase-1]}`;if($('#locationPill')?.textContent!==label)$('#locationPill').textContent=label}
function navigate(n){const p=progress();if(Math.hypot(p.x-n.x,p.y-n.y)<155){interact(n)}else autowalk={x:n.x-(n.type==='npc'?145:50),y:Math.min(706,Math.max(586,n.y+30)),node:n}}
function routeTaskToMemory(i){const n=NODES.find(n=>n.type==='memory'&&n.index===i);if(n)navigate(n)}
function routeTaskToNpc(i){const g=getProfileByEvent(story().id,i);const n=NODES.find(n=>n.type==='npc'&&n.index===(g?.index??i));if(n)navigate(n)}
function routeTask(t){const p=progress();let n;if(t==='memory')n=NODES.find(n=>n.type==='memory'&&!p.fragments.includes(n.index));if(t==='npc')n=NODES.find(n=>n.type==='npc'&&!p.talks.includes(n.index));if(t==='pearl')n=NODES.find(n=>n.type==='pearl'&&!p.pearls.includes(n.index));if(t==='puzzle'||t==='words'||t==='timeline'||t==='quiz')n=NODES.find(n=>n.type===t);if(t==='decision'){decision();return}if(t==='story'){storyBook();return}if(n)navigate(n);else toast('Esa meta ya está completada. Explora otras misiones.');}
function routeToNext(){const p=progress(),c=completion(p);if(!c[0])routeTask('npc');else if(!c[1])routeTask('pearl');else if(!c[2])routeTask('puzzle');else if(!c[3])routeTask('words');else if(!c[4])routeTask('timeline');else if(!c[5])routeTask('quiz');else if(!c[6])decision();else if(p.fragments.length<6)routeTask('memory');else if(!c[7])storyBook();else navigate(NODES.find(n=>n.type==='finish'))}
function interact(n){if(n.type==='npc')dialogue(n.index);else if(n.type==='memory')chapterMoment(n.index);else if(n.type==='pearl')pearl(n.index);else if(n.type==='puzzle')puzzle();else if(n.type==='words')wordsearch();else if(n.type==='timeline')timeline();else if(n.type==='quiz')openQuiz(0);else if(n.type==='finish')finish()}
function chapterMoment(i){
 const s=story(),p=progress(),f=storyFragment(s,i),was=p.fragments.includes(i);
 const witnesses=getPeople(s.id).filter(g=>g.entries.some(e=>e.after===i));
 const narrator=witnesses.find(g=>g.name!==f.name)||witnesses[0]||null;
 const witness=narrator?`<div class="memory-witness"><img src="${person('hero',s,narrator.index)}" alt=""><div><b>${esc(narrator.name)}</b><small>Personaje vinculado a esta etapa · no es una cita literal</small></div></div>`:'<div class="memory-witness"><b>Cuaderno del viajero</b></div>';
 const body=`<div class="memory-lesson"><small class="tiny-caps">MOMENTO ${i+1} DE 6 · ${esc(f.tag||'') }</small><h3>${esc(f.title)}</h3>${witness}<p>${esc(f.text)}</p><p><strong>Su importancia:</strong> ${esc(f.role||s.value)}.</p><small>Referencia: ${esc(f.reference||s.reference)}</small><div class="modal-actions"><button class="btn strong" id="saveMemory">${was?'✓ Volver al camino':'📜 Guardar este momento'}</button></div>${sourceButtons(s)}</div>`;
 openModal('Un momento de '+s.name,body,'CRONOLOGÍA');
 $('#saveMemory').onclick=()=>{if(!p.fragments.includes(i)){p.fragments.push(i);p.fragments.sort((a,b)=>a-b);gain(s.id+':fragment:'+i,45,10);save()}closeModal();if(p.fragments.length===6)toast('¡Ya tienes las seis escenas! Pulsa B para reconstruir la historia.')};
}
function toast(t){const b=$('#toast');if(!b)return;b.textContent=t;b.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>b.classList.remove('visible'),2700)}
const kbh=e=>{if(state.screen!=='game'||modalOpen||['TEXTAREA','INPUT','SELECT'].includes(document.activeElement?.tagName))return;const v={ArrowUp:'up',w:'up',W:'up',ArrowDown:'down',s:'down',S:'down',ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right'}[e.key];if(v){e.preventDefault();held.add(v);autowalk=null}};
window.addEventListener('keydown',kbh);window.addEventListener('keyup',e=>{const v={ArrowUp:'up',w:'up',W:'up',ArrowDown:'down',s:'down',S:'down',ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right'}[e.key];if(v)held.delete(v)});window.addEventListener('blur',()=>held.clear());
window.addEventListener('keydown',e=>{if(state.screen!=='game'||modalOpen||e.altKey||e.ctrlKey||e.metaKey||e.repeat||['TEXTAREA','INPUT','SELECT'].includes(document.activeElement?.tagName))return;const key=e.key.toLowerCase();if(key==='e'){e.preventDefault();if(bubbleIndex!==null){activeBubble?.go();return}const n=nearestNode();if(n)interact(n);else toast('Acércate a un personaje, perla o desafío para interactuar.')}else if(key==='b'){e.preventDefault();storyBook()}else if(key==='g'){e.preventDefault();routeToNext()}else if(key==='m'){e.preventDefault();menu()}else if(key==='h'){e.preventDefault();controls()}else if(key==='p'){e.preventDefault();pickCharacter()}});
function openModal(title,body,extra=''){if(bubbleIndex!==null)closeBubble();lastFocus=document.activeElement;if($('#overlay'))$('#overlay').remove();modalOpen=true;held.clear();const div=elem('div',{class:'overlay',id:'overlay',role:'dialog','aria-modal':'true','aria-label':title},`<div class="modal"><header class="modal-header"><div><small class="tiny-caps">CAMINOS DE FE · ${extra||'DESCUBRIMIENTO'}</small><h2>${esc(title)}</h2></div><button class="close-modal" id="closeModal" aria-label="Cerrar">✕</button></header><div class="modal-content" id="modalContent">${body}</div></div>`);document.body.append(div);$('#closeModal').onclick=closeModal;div.addEventListener('click',e=>{if(e.target===div)closeModal()});requestAnimationFrame(()=>$('#closeModal')?.focus())}
function closeModal(){clearInterval(successTimer);successTimer=null;const o=$('#overlay');if(o)o.remove();modalOpen=false;if(lastFocus?.isConnected)lastFocus.focus({preventScroll:true});lastFocus=null;save();if(state.screen==='game'){refreshQuest();} }
function refreshQuest(){if(state.screen==='game'){const p=progress(),q=completion(p);if($('#hudXp'))updateHud();if($('.next-goal b'))$('.next-goal b').textContent=objective(p);if($('.game-bottom span'))$('.game-bottom span').textContent='✦ '+objective(p);if($('.quest-meter b'))$('.quest-meter b').textContent=q.filter(Boolean).length+'/8';if($('#storyParts'))$('#storyParts').textContent=(p.fragments||[]).length+'/6 escenas · '+learnedCharacters(story(),p)+'/'+getPeople(story().id).length+' personajes';if($('.quest-meter i'))$('.quest-meter i').style.width=(q.filter(Boolean).length/8*100)+'%';$$('[data-chrono]').forEach(b=>b.classList.toggle('read',p.fragments.includes(+b.dataset.chrono)));$$('.quest-task').forEach((b,i)=>{b.classList.toggle('achieved',q[i]);b.querySelector('.task-icon').textContent=q[i]?'✓':'○'});$$('.node-memory').forEach(b=>{const n=NODES[+b.dataset.node];if(p.fragments.includes(n.index))b.querySelector('.memory-chapter-icon').textContent='✓'});$$('.node-pearl').forEach(b=>{const i=+b.dataset.node;const n=NODES[i];if(p.pearls.includes(n.index))b.querySelector('.floating-gem').textContent='✓'});$$('.node-npc').forEach(b=>{const n=NODES[+b.dataset.node];b.querySelector('.npc-question').textContent=p.talks.includes(n.index)?'✓':'···'})}}
function sourceButtons(s){return `<div class="source-links">${url(s.source)?`<a href="${esc(s.source)}" target="_blank" rel="noopener noreferrer">🔗 Publicación original ↗</a>`:''}${url(s.bible)?`<a href="${esc(s.bible)}" target="_blank" rel="noopener noreferrer">📖 Biblia en JW.org ↗</a>`:''}</div>`}
function storyFragment(s,i){
 const e=getActor(s,i);if(e)return {tag:e.stage,title:e.title,text:e.text+' '+e.why,name:e.name,role:e.role,reference:e.reference};
 const seq=s.sequence||[];return {tag:'ESCENA '+(i+1),title:seq[Math.min(i,3)]||s.name,text:s.summary,name:s.name,role:'Personaje del relato',reference:s.reference};
}
function closeBubble(){document.querySelector('.speech-bubble')?.remove();bubbleIndex=null;save();refreshQuest()}
let activeBubble=null;
function placeBubble(){
 const b=document.querySelector('.speech-bubble');if(!b||bubbleIndex===null||state.screen!=='game')return;
 const v=$('#viewport'),node=[...document.querySelectorAll('.node-npc')].find(el=>NODES[+el.dataset.node].index===bubbleIndex);if(!node||!v)return;
 const r=v.getBoundingClientRect(),a=node.getBoundingClientRect();const w=b.offsetWidth||290,h=b.offsetHeight||235;
 const headX=a.left-r.left+a.width*.53,headY=a.top-r.top+20;
 const fitsRight=headX+50+w<r.width-12;
 const x=fitsRight?headX+46:Math.max(10,headX-w-39);
 const y=Math.max(10,Math.min(r.height-h-10,headY-48));
 b.style.left=Math.max(8,Math.min(r.width-w-8,x))+'px';b.style.top=y+'px';
 b.classList.toggle('bubble-left',!fitsRight);
 b.style.setProperty('--tail-y',Math.max(23,Math.min(h-25,headY-y))+'px');
}
function dialogue(i,automatic=false){
 const s=story(),p=progress(),g=getProfileByEvent(s.id,i),e=getActor(s,i);
 if(!g)return;
 document.querySelector('.speech-bubble')?.remove();bubbleIndex=g.index;autowalk=null;held.clear();
 const node=[...document.querySelectorAll('.node-npc')].find(el=>NODES[+el.dataset.node].index===g.index),v=$('#viewport');if(!node||!v)return;
 const b=document.createElement('section');b.className='speech-bubble story-dialogue-v22 unique-npc-v25';b.setAttribute('role','dialog');b.setAttribute('aria-modal','false');b.setAttribute('aria-label','Conversación con '+g.name);
 const seen=hasMet(g,p);
 const intro=g.mode==='parabola'?'Hola, represento a '+g.name+'. Esta es una parábola, no una biografía histórica.':'Hola, soy '+g.name+'.';
 const panels=[{label:'QUIÉN SOY',headline:'Conoce a '+g.name,body:intro+' '+(g.bio||''),reference:g.reference,link:g.source||s.source||s.bible}];
 for(const entry of g.entries){
  panels.push({label:'ETAPA '+(entry.after+1)+' · '+(entry.stage||'RELATO'),headline:entry.title||'Un momento de la historia',body:(entry.text||'')+(entry.why?' ¿Por qué importa? '+entry.why:''),reference:entry.reference||g.reference,link:entry.verseUrl||g.source||s.bible||s.source});
 }
 if(g.cross)panels.push({label:'CONEXIÓN ENTRE HISTORIAS',headline:'Una relación que vale investigar',body:g.cross,reference:g.reference,link:g.source||s.bible||s.source});
 let page=0;
 const collect=()=>{
  if(!seen){for(const ix of g.ids)if(!p.talks.includes(ix))p.talks.push(ix);gain(s.id+':persona:'+g.index,75,20);save()}
  const allMet=learnedCharacters(s,p)===getPeople(s.id).length;
  const allSix=p.fragments.length===6;
  closeBubble();
  if(allSix&&!p.storyAssembled)toast('¡Reuniste las seis escenas principales! Abre el cuaderno con B.');
  if(allMet)toast('¡Conociste a todo el elenco sin personajes repetidos!');
 };
 const paint=()=>{
  const item=panels[page],isLast=page===panels.length-1;
  b.innerHTML=`<div class="dialogue-top"><span class="dialogue-act">${esc(item.label)}</span><button type="button" class="bubble-close" aria-label="Cerrar conversación">×</button></div><div class="dialogue-speaker"><div class="speaker-avatar"><img src="${person('hero',s,g.index)}" alt=""></div><div><b>${esc(g.name)}</b><span>${esc(g.entries.length>1?g.entries.length+' momentos de su historia':'Un encuentro único')}</span></div></div><div class="dialogue-headline">${esc(item.headline)}</div><p class="dialogue-prose" tabindex="0">${esc(item.body)}</p><div class="dialogue-footer"><span class="page-index">${page+1} de ${panels.length}</span><button type="button" class="bubble-next">${isLast?(seen?'✓ Volver a explorar':'✓ Guardar historia'):'Continuar →'}</button><a href="${esc(url(item.link)||url(s.bible)||url(s.source)||'https://www.jw.org/es/biblioteca/')}" target="_blank" rel="noopener noreferrer" aria-label="Ver referencia del relato" title="${esc(item.reference)}">📖</a></div><small class="npc-literary-note">Diálogo recreado para aprender; no son palabras textuales.</small>`;
  b.querySelector('.bubble-close').onclick=ev=>{ev.stopPropagation();closeBubble()};
  b.querySelector('.bubble-next').onclick=ev=>{ev.stopPropagation();if(!isLast){page++;paint()}else collect()};
  b.querySelector('a').onclick=ev=>ev.stopPropagation();
  requestAnimationFrame(placeBubble);
 };
 activeBubble={idx:g.index,go:()=>{if(page<panels.length-1){page++;paint()}else collect()},close:closeBubble};
 v.appendChild(b);b.addEventListener('click',ev=>ev.stopPropagation());paint();
 requestAnimationFrame(()=>{placeBubble();b.querySelector('.bubble-next')?.focus({preventScroll:true})});
}
function pickCharacter(){const cards=['female','male'].flatMap(g=>Array.from({length:4},(_,i)=>`<button type="button" data-sex="${g}" data-style="${i}" aria-pressed="${state.gender===g&&state.avatar===i}"><img src="${asset(`assets/protagonistas-v23/${g}-${i}.svg`)}" alt="${g==='female'?'Exploradora':'Explorador'} · modelo ${i+1}"><b>${g==='female'?'Exploradora':'Explorador'}</b><small>Estilo ${i+1}</small></button>`)).join('');openModal('Crea tu protagonista',`<p class="character-picker-intro">Elige a quién quieres acompañar en tu aventura. Puedes cambiarlo en cualquier momento pulsando P.</p><div class="character-picker">${cards}</div>`,'8 ESTILOS');$$('[data-sex]').forEach(b=>b.onclick=()=>{state.gender=b.dataset.sex;state.avatar=+b.dataset.style;save();closeModal();render('game')})}

function showCast(){
 const s=story(),p=progress(),all=getPeople(s.id);
 const html=`<div class="cast-intro"><h3>Una sola persona, toda su historia</h3><p>${esc(s.name)}: ${all.length} personajes visibles, ${getCast(s.id).length} intervenciones cronológicas. Los protagonistas que regresan en el relato se presentan una sola vez y sus acontecimientos se agrupan dentro de su biografía.</p></div><div class="cast-roster">${all.map(g=>`<article class="cast-entry ${hasMet(g,p)?'discovered':''}"><img src="${person('hero',s,g.index)}" alt="Retrato de ${esc(g.name)}"><div><small>APARECE EN LA ETAPA ${g.after+1} · ${g.entries.length} ${g.entries.length===1?'MOMENTO':'MOMENTOS'}</small><h4>${esc(g.name)}</h4><p>${esc(g.bio||'Participa en el desarrollo del relato bíblico.')}</p>${g.cross?`<p class="cast-connection"><b>✦ Conexión:</b> ${esc(g.cross)}</p>`:''}<details class="cast-episodes"><summary>Ver sus ${g.entries.length} aportaciones en orden</summary>${g.entries.map(en=>`<div class="cast-episode"><b>${esc(en.stage||'Etapa '+(en.after+1))}: ${esc(en.title)}</b><p>${esc(en.text)}</p><p><em>${esc(en.why)}</em></p><small>${esc(en.reference)}</small></div>`).join('')}</details><span>📖 ${esc(g.sourceTitle||'Pasajes bíblicos y publicaciones')} · <a href="${esc(url(g.source)||url(s.source)||url(s.bible))}" target="_blank" rel="noopener noreferrer">Consultar fuente ↗</a></span></div><button data-find-actor="${g.index}" class="btn small ${hasMet(g,p)?'subtle':'strong'}">${hasMet(g,p)?'Escuchar de nuevo':'Encontrar en el mapa'}</button></article>`).join('')}</div>`;
 openModal('Elenco del capítulo · '+s.name,html,'PERSONAJES ÚNICOS');
 $$('[data-find-actor]').forEach(b=>b.onclick=()=>{const ix=+b.dataset.findActor;closeModal();routeTaskToNpc(ix)});
}
function completedChallenge(title,message,options={}){
 clearInterval(successTimer);const next=options.next||null;let sec=options.seconds||8;
 const html=`<div class="challenge-victory" role="status" aria-live="polite"><div class="victory-symbol">✓</div><span class="tiny-caps">${options.reveal?'RESPUESTA CONSULTADA':'RETO SUPERADO'}</span><h3>${esc(title)}</h3><p>${esc(message)}</p><p class="reward-achieved">${options.reward?esc(options.reward):'Tu progreso quedó guardado en la aventura.'}</p><div class="modal-actions"><button class="btn strong" id="victoryReturn">↩ Volver al juego</button>${options.proofUrl?`<a class="btn proof-link" href="${esc(options.proofUrl)}" target="_blank" rel="noopener noreferrer">🔎 Comprobar en JW.org ↗</a>`:''}${next?'<button class="btn outline" id="victoryNext">Siguiente actividad →</button>':''}</div>${options.sourceLabel?`<small>Fuente: ${esc(options.sourceLabel)}</small>`:''}<small>Regreso automático en <b id="victoryCount">${sec}</b> segundos · También puedes pulsar Esc</small></div>`;
 openModal('¡Felicidades! '+title,html,'MISIÓN COMPLETADA');
 const overlay=$('#overlay');
 const finish=()=>{if($('#overlay')!==overlay)return;clearInterval(successTimer);successTimer=null;closeModal()};
 $('#victoryReturn').onclick=finish;
 if(next)$('#victoryNext').onclick=()=>{finish();next()};
 successTimer=setInterval(()=>{if($('#overlay')!==overlay){clearInterval(successTimer);return}sec--;if($('#victoryCount'))$('#victoryCount').textContent=sec;if(sec<=0)finish()},1000);
}
function storyBook(){const s=story(),p=progress(),discovered=new Set(p.fragments||[]);
 const cards=[0,1,2,3,4,5].map(i=>{const f=storyFragment(s,i);return `<article class="story-piece ${discovered.has(i)?'collected':'locked'}"><span>${String(i+1).padStart(2,'0')}</span><div><small>${esc(f.tag)} · ${esc(f.name||s.name)}</small><h4>${esc(f.title)}</h4><p>${discovered.has(i)?esc(f.text):'Este momento se descubre en el mapa, junto al símbolo 📜.'}</p></div><b>${discovered.has(i)?'✓':'⌁'}</b></article>`}).join('');
 openModal('El relato que estás reconstruyendo',`<div class="storybook"><div class="book-top"><div><span class="tiny-caps">CUADERNO DE VIAJE · ${esc(s.name)}</span><h3>${[...discovered].filter(x=>x<6).length}/6 escenas esenciales</h3><p>Reúne los seis momentos fundamentales y conoce al elenco adicional para comprender el contexto de cada escena.</p></div><div class="book-progress">${discovered.size}/6</div></div><div class="story-pieces">${cards}</div><div class="study-source">${sourceButtons(s)}</div><div class="modal-actions">${discovered.size===6?`<button class="btn strong" id="assembleBtn">${p.storyAssembled?'✓ Ver relato reunido':'🧩 Unir ahora todo el relato'}</button>`:`<button class="btn strong" id="routeVoices">Encontrar siguiente momento 📜 →</button>`}</div></div>`,'MI HISTORIA');
 $('#assembleBtn')?.addEventListener('click',assembleStory);$('#routeVoices')?.addEventListener('click',()=>{closeModal();routeTask('memory')});
}
function assembleStory(){const s=story(),p=progress();if(p.fragments.length<6){storyBook();return}if(!Array.isArray(p.storyOrder)||p.storyOrder.length!==6){p.storyOrder=[3,0,5,2,1,4];}function draw(){const list=$('#assembleList');if(!list)return;list.innerHTML=p.storyOrder.map((v,i)=>{const f=storyFragment(s,v);return `<div class="assembly-item"><b>${i+1}</b><div><small>ESCENA ${v+1} · ${esc(f.name||s.name)}</small><strong>${esc(f.title)}</strong><p>${esc(f.text)}</p></div><div class="assembly-controls"><button data-move="${i}:up" aria-label="Subir fragmento ${v+1}">↑</button><button data-move="${i}:down" aria-label="Bajar fragmento ${v+1}">↓</button></div></div>`}).join('');$$('[data-move]').forEach(b=>b.onclick=()=>{const [str,dir]=b.dataset.move.split(':'),i=+str,j=i+(dir==='up'?-1:1);if(j<0||j>=6)return;[p.storyOrder[i],p.storyOrder[j]]=[p.storyOrder[j],p.storyOrder[i]];save();draw();const target=$(`[data-move="${j}:${dir}"]`);target?.focus()});}
 openModal('Une las seis partes de la historia',`<div class="assembly"><p>Coloca los seis fragmentos en el orden correcto: desde la presentación de la historia hasta la lección que aprendemos. Puedes usar las flechas de cada tarjeta con el mouse o con <b>Tab + Enter</b>.</p><div id="assembleList"></div><div class="modal-actions"><button id="checkAssembly" class="btn strong">Comprobar mi historia</button><button id="backToBook" class="btn outline">Volver al cuaderno</button></div><div id="assemblyFeedback" aria-live="polite">${p.storyAssembled?'<div class="feedback success">✓ Este relato ya fue reconstruido.</div>':''}</div></div>`,'LA HISTORIA COMPLETA');draw();$('#backToBook').onclick=storyBook;
 $('#checkAssembly').onclick=()=>{if(p.storyOrder.every((v,i)=>v===i)){if(!p.storyAssembled){p.storyAssembled=true;gain(s.id+':assembled',260,90)}$('#assemblyFeedback').innerHTML=`<div class="feedback success"><b>¡Ahora el relato tiene sentido!</b><p>${esc(s.summary)}</p><p><strong>¿Qué aprendemos?</strong> ${esc(s.value)}.</p>${sourceButtons(s)}</div>`;save();completedChallenge('¡Historia reconstruida!', 'Ordenaste correctamente los seis acontecimientos principales y comprendiste el relato.',{reward:'+260 XP · +90 luceros',seconds:9});}else{$('#assemblyFeedback').innerHTML='<div class="feedback error">Todavía hay escenas fuera de orden. Comienza con el contexto y termina con la enseñanza.</div>'}};
}
function qFromPearl(i){const s=story(),q=VQ[s.id]?.[i+3];if(!q)throw Error('No hay pregunta revisada para la perla '+s.id+' '+i);return {...q,id:s.id+'-perla-revisada-v24-'+i,nivel:['Investigador','Maestro','Experto'][i]}}
